const std::string &SupportTickets::getValueOfId() const noexcept
{
    static const std::string defaultValue = std::string();
    if(id_)
        return *id_;
    return defaultValue;
}
const std::shared_ptr<std::string> &SupportTickets::getId() const noexcept
{
    return id_;
}
void SupportTickets::setId(const std::string &pId) noexcept
{
    id_ = std::make_shared<std::string>(pId);
    dirtyFlag_[0] = true;
}
void SupportTickets::setId(std::string &&pId) noexcept
{
    id_ = std::make_shared<std::string>(std::move(pId));
    dirtyFlag_[0] = true;
}
const typename SupportTickets::PrimaryKeyType & SupportTickets::getPrimaryKey() const
{
    assert(id_);
    return *id_;
}

const std::string &SupportTickets::getValueOfTicketNumber() const noexcept
{
    static const std::string defaultValue = std::string();
    if(ticketNumber_)
        return *ticketNumber_;
    return defaultValue;
}
const std::shared_ptr<std::string> &SupportTickets::getTicketNumber() const noexcept
{
    return ticketNumber_;
}
